import os
from azure.storage.blob import BlobServiceClient

def get_blob_service_client():
    connection_string = os.getenv("AZURE_STORAGE_CONNECTION_STRING")
    if not connection_string:
        raise ValueError("AZURE_STORAGE_CONNECTION_STRING environment variable not set.")
    return BlobServiceClient.from_connection_string(connection_string)

from storage_client import get_blob_service_client

def get_object_metadata(container_name: str, blob_name: str):
    blob_service_client = get_blob_service_client()
    blob_client = blob_service_client.get_blob_client(container=container_name, blob=blob_name)
    properties = blob_client.get_blob_properties()
    metadata = {k: v for k, v in properties.metadata.items()} if properties.metadata else {}
    return {
        "name": properties.name,
        "container": properties.container,
        "size": properties.size,
        "creation_time": properties.creation_time.isoformat() if properties.creation_time else None,
        "last_modified": properties.last_modified.isoformat() if properties.last_modified else None,
        "content_settings": {
            "content_type": properties.content_settings.content_type,
            "content_md5": properties.content_settings.content_md5,
        },
        "metadata": metadata
    }

from storage_client import get_blob_service_client

def list_objects_with_prefix(container_name: str, prefix: str = ""):
    blob_service_client = get_blob_service_client()
    container_client = blob_service_client.get_container_client(container_name)
    blob_list = []
    for blob in container_client.list_blobs(name_starts_with=prefix):
        blob_list.append({
            "name": blob.name,
            "size": blob.size,
            "last_modified": blob.last_modified.isoformat() if blob.last_modified else None,
            "etag": blob.etag,
            "content_settings": {
                "content_type": blob.content_settings.content_type,
            }
        })
    return blob_list

import os
import requests
import json

def run_ocr_on_stored_document(document_url: str):
    endpoint = os.getenv("AZURE_VISION_ENDPOINT")
    key = os.getenv("AZURE_VISION_KEY")

    if not endpoint or not key:
        raise ValueError("AZURE_VISION_ENDPOINT and AZURE_VISION_KEY environment variables not set.")

    # Using Azure AI Vision Read API for OCR
    ocr_url = f"{endpoint}/vision/v3.2/read/sync"
    headers = {
        "Ocp-Apim-Subscription-Key": key,
        "Content-Type": "application/json"
    }
    data = {"url": document_url}

    try:
        response = requests.post(ocr_url, headers=headers, json=data)
        response.raise_for_status()
        result = response.json()

        extracted_text = []
        if 'analyzeResult' in result and 'readResults' in result['analyzeResult']:
            for page in result['analyzeResult']['readResults']:
                for line in page['lines']:
                    extracted_text.append(line['text'])
        return {"extracted_text": "\n".join(extracted_text), "full_response": result}
    except requests.exceptions.RequestException as e:
        return {"error": f"OCR failed: {e}", "details": response.text if response else "No response"}

import os
import requests
import json
import uuid

def translate_text(text: str, target_language: str = "en", source_language: str = "auto"):
    endpoint = os.getenv("AZURE_TRANSLATOR_ENDPOINT")
    key = os.getenv("AZURE_TRANSLATOR_KEY")
    region = os.getenv("AZURE_TRANSLATOR_REGION")

    if not endpoint or not key or not region:
        raise ValueError("AZURE_TRANSLATOR_ENDPOINT, AZURE_TRANSLATOR_KEY, and AZURE_TRANSLATOR_REGION environment variables not set.")

    path = '/translate'
    constructed_url = endpoint + path

    params = {
        'api-version': '3.0',
        'to': target_language
    }
    if source_language != "auto":
        params['from'] = source_language

    headers = {
        'Ocp-Apim-Subscription-Key': key,
        'Ocp-Apim-Subscription-Region': region,
        'Content-type': 'application/json',
        'X-ClientTraceId': str(uuid.uuid4())
    }

    body = [{
        'text': text
    }]

    try:
        response = requests.post(constructed_url, params=params, headers=headers, json=body)
        response.raise_for_status()
        translation_result = response.json()
        translated_text = translation_result[0]['translations'][0]['text']
        return {"translated_text": translated_text, "full_response": translation_result}
    except requests.exceptions.RequestException as e:
        return {"error": f"Translation failed: {e}", "details": response.text if response else "No response"}

import os
from openai import AzureOpenAI

def summarize_text(text: str, max_tokens: int = 150):
    azure_endpoint = os.getenv("AZURE_OPENAI_ENDPOINT")
    api_key = os.getenv("AZURE_OPENAI_API_KEY")
    api_version = os.getenv("AZURE_OPENAI_API_VERSION", "2023-05-15")
    deployment_name = os.getenv("AZURE_OPENAI_DEPLOYMENT_NAME")

    if not azure_endpoint or not api_key or not deployment_name:
        raise ValueError("AZURE_OPENAI_ENDPOINT, AZURE_OPENAI_API_KEY, and AZURE_OPENAI_DEPLOYMENT_NAME environment variables must be set.")

    client = AzureOpenAI(
        azure_endpoint=azure_endpoint,
        api_key=api_key,
        api_version=api_version,
    )

    try:
        response = client.chat.completions.create(
            model=deployment_name,
            messages=[
                {"role": "system", "content": "You are a helpful assistant that summarizes text."},
                {"role": "user", "content": f"Summarize the following text:\n\n{text}"}
            ],
            max_tokens=max_tokens,
            temperature=0.7,
        )
        summary = response.choices[0].message.content.strip()
        return {"summary": summary, "full_response": response.model_dump_json()}
    except Exception as e:
        return {"error": f"Summarization failed: {e}"}

import os
from openai import AzureOpenAI
from typing import List

def get_embeddings(texts: List[str]):
    azure_endpoint = os.getenv("AZURE_OPENAI_ENDPOINT")
    api_key = os.getenv("AZURE_OPENAI_API_KEY")
    api_version = os.getenv("AZURE_OPENAI_API_VERSION", "2023-05-15")
    embedding_deployment_name = os.getenv("AZURE_OPENAI_EMBEDDING_DEPLOYMENT_NAME")

    if not azure_endpoint or not api_key or not embedding_deployment_name:
        raise ValueError("AZURE_OPENAI_ENDPOINT, AZURE_OPENAI_API_KEY, and AZURE_OPENAI_EMBEDDING_DEPLOYMENT_NAME environment variables must be set.")

    client = AzureOpenAI(
        azure_endpoint=azure_endpoint,
        api_key=api_key,
        api_version=api_version,
    )

    try:
        response = client.embeddings.create(
            input=texts,
            model=embedding_deployment_name,
        )
        embeddings = [entry.embedding for entry in response.data]
        return {"embeddings": embeddings, "full_response": response.model_dump_json()}
    except Exception as e:
        return {"error": f"Embedding generation failed: {e}"}
